const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const money=n=>new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(Number(n||0));
const adminSessionKey = "asServiciosAdminSessionV1";
let token=sessionStorage.getItem(adminSessionKey)||"", data={products:[],categories:[],banners:[],orders:[],requests:[],virtualMessages:[],quotes:[],users:[],contentRows:[],config:{},whatsappCloud:{configured:false},currentUser:null,permissions:{}};
const adminThemeKey = "asServiciosAdminThemeV2";
const permissionModules=[
  ["dashboard","Dashboard"],["products","Productos"],["categories","Categorías"],["banners","Carrusel"],
  ["orders","Pedidos"],["requests","Solicitudes"],["virtual","AS Virtual"],["office","Oficina Virtual"],
  ["content","Contenido Web"],["users","Usuarios y permisos"],["settings","Configuración"]
];

const adminMenuStoreKey = "asServiciosAdminMenuCollapsed";
function isAdminMobile(){ return window.matchMedia("(max-width: 980px)").matches; }
function setAdminMenu(open){
  const shell=$("#adminShell"), btn=$("#adminMenuToggle"), overlay=$("#adminMenuOverlay");
  if(!shell) return;
  if(isAdminMobile()){
    shell.classList.toggle("menu-open", !!open);
    document.body.classList.toggle("admin-menu-open", !!open);
    btn?.setAttribute("aria-expanded", open ? "true" : "false");
    overlay?.setAttribute("aria-hidden", open ? "false" : "true");
  } else {
    const collapsed = open === undefined ? shell.classList.contains("admin-menu-collapsed") : !open;
    shell.classList.toggle("admin-menu-collapsed", collapsed);
    localStorage.setItem(adminMenuStoreKey, collapsed ? "1" : "0");
    btn?.setAttribute("aria-expanded", collapsed ? "false" : "true");
  }
}
function initAdminMenu(){
  const shell=$("#adminShell"), btn=$("#adminMenuToggle"), overlay=$("#adminMenuOverlay");
  if(!shell || !btn) return;
  if(!isAdminMobile() && localStorage.getItem(adminMenuStoreKey)==="1") shell.classList.add("admin-menu-collapsed");
  btn.setAttribute("aria-expanded", isAdminMobile() ? "false" : (shell.classList.contains("admin-menu-collapsed") ? "false" : "true"));
  btn.addEventListener("click",()=>{
    if(isAdminMobile()) setAdminMenu(!shell.classList.contains("menu-open"));
    else setAdminMenu(shell.classList.contains("admin-menu-collapsed"));
  });
  overlay?.addEventListener("click",()=>setAdminMenu(false));
  window.addEventListener("keydown",e=>{if(e.key==="Escape" && shell.classList.contains("menu-open")) setAdminMenu(false)});
  window.addEventListener("resize",()=>{
    if(!isAdminMobile()){ shell.classList.remove("menu-open"); document.body.classList.remove("admin-menu-open"); overlay?.setAttribute("aria-hidden","true"); }
    btn.setAttribute("aria-expanded", isAdminMobile() ? (shell.classList.contains("menu-open")?"true":"false") : (shell.classList.contains("admin-menu-collapsed")?"false":"true"));
  });
}


function isAuthError(e){
  const m=String(e?.message||e||"");
  return /SESION_REQUERIDA|SESION_INVALIDA|SESION_INVALIDA_O_EXPIRADA|USUARIO_INACTIVO/.test(m);
}
function saveSession(t){token=String(t||"");if(token)sessionStorage.setItem(adminSessionKey,token);else sessionStorage.removeItem(adminSessionKey)}
function showLogin(message="",type="error"){
  $("#adminShell")?.classList.add("hidden");
  $("#adminLoginScreen")?.classList.remove("hidden");
  if(message){
    const box=$("#adminLoginMessage");
    if(box){box.classList.remove("hidden","success","error");box.classList.add(type);box.textContent=message;}
  }
  setTimeout(()=>$("#adminLoginUser")?.focus(),80);
}
function hideLogin(){
  $("#adminLoginScreen")?.classList.add("hidden");
  $("#adminLoginMessage")?.classList.add("hidden");
}
function authMessageFromError(e){
  const m=String(e?.message||e||"");
  if(m.includes("SEGURIDAD_NO_INICIALIZADA")) return "La seguridad aún no está inicializada. Ejecuta instalarSeguridadCPANEL() una vez en Google Apps Script.";
  if(m.includes("LOGIN_BLOQUEADO_TEMPORALMENTE")) return "Demasiados intentos. El acceso quedó bloqueado temporalmente por seguridad.";
  if(m.includes("USUARIO_O_CLAVE_INVALIDOS")) return "Usuario o contraseña incorrectos.";
  if(m.includes("USUARIO_INACTIVO")) return "Este usuario está desactivado.";
  if(m.includes("SESION")) return "La sesión expiró. Ingresa nuevamente.";
  if(m.includes("API_SCRIPT_LOAD_ERROR")) return "El Apps Script no pudo cargarse. Revisa el despliegue y la URL configurada.";
  if(m.includes("API_TIMEOUT")||m.includes("API_CONFIRMATION_TIMEOUT")) return "Servidor y BD disponibles, pero el canal de autenticación no confirmó el login. Esta versión usa automáticamente un segundo transporte de respaldo.";
  if(m.includes("LOGIN_SIN_TOKEN")) return "El servidor respondió, pero no entregó una sesión válida. Ejecuta diagnosticarAccesoCPANEL() en Apps Script.";
  if(m.includes("HTTP_")) return "El servidor respondió con un error HTTP. Revisa permisos y despliegue del Web App.";
  return `No fue posible iniciar sesión. Detalle: ${m||"ERROR_DESCONOCIDO"}`;
}
function setLoginServerStatus(state,text){
  const el=$("#adminLoginServerStatus");if(!el)return;
  el.classList.remove("is-online","is-offline","is-checking");el.classList.add(state==="online"?"is-online":state==="offline"?"is-offline":"is-checking");
  const b=el.querySelector("b");if(b)b.textContent=text||"Verificando servidor…";
}
async function checkLoginServer(){
  if(!AleAPI.configured()){setLoginServerStatus("offline","URL de Apps Script no configurada");return false;}
  setLoginServerStatus("checking","Verificando servidor…");
  try{const h=await AleAPI.health();if(h?.ok!==false){setLoginServerStatus("online","Servidor y BD disponibles");return true;}throw new Error(h?.error||"HEALTH_ERROR");}
  catch(e){console.error("CPANEL health",e);setLoginServerStatus("offline","Apps Script sin respuesta · revisar despliegue");return false;}
}
function can(moduleName,action="read"){
  if(String(data.currentUser?.rol||"").toUpperCase()==="ADMIN") return true;
  return !!data.permissions?.[moduleName]?.[action];
}
function showAdmin(){hideLogin();$("#adminShell")?.classList.remove("hidden")}
function applyCurrentUser(){
  const u=data.currentUser||{};
  if($("#currentAdminName"))$("#currentAdminName").textContent=u.nombre||u.usuario||"Usuario";
  if($("#currentAdminRole"))$("#currentAdminRole").textContent=String(u.rol||"").toUpperCase();
  applyPermissionsToUI();
}
function applyPermissionsToUI(){
  $$("[data-module]").forEach(el=>{
    const moduleName=el.dataset.module;
    el.classList.toggle("hidden",!can(moduleName,"read"));
  });
  const active=$(".admin-nav button.active:not(.hidden)") || $(".admin-nav button:not(.hidden)");
  if(active && !$("#view-"+active.dataset.view)?.classList.contains("active")) active.click();

  const writeMap={
    products:["#newProduct","#saveProduct"],
    categories:["#newCategory","#saveCategory"],
    banners:["#newBanner","#saveBanner"],
    office:["#newQuote","#generateQuote","#generateAndEmail","#generateAndWhatsapp","#addQuoteItem"],
    content:["#saveWebContent","#saveWebContentBottom"],
    users:["#newAdminUser","#saveAdminUser"],
    settings:["#saveSettings","#saveWhatsAppCloud","#clearWhatsAppToken"]
  };
  Object.entries(writeMap).forEach(([moduleName,selectors])=>{
    selectors.forEach(sel=>$$(sel).forEach(el=>{el.disabled=!can(moduleName,"write");el.classList.toggle("permission-disabled",!can(moduleName,"write"))}));
  });
}

function toast(msg,type="success",detail=""){
  const t=$("#adminToast"); if(!t) return;
  const icon=type==="error"?"x-lg":type==="info"?"info-lg":"check-lg";
  t.className=`toast admin-action-toast ${type}`;
  t.innerHTML=`<span class="toast-icon"><i class="bi bi-${icon}"></i></span><span class="toast-copy"><strong>${esc(msg)}</strong>${detail?`<small>${esc(detail)}</small>`:""}</span>`;
  requestAnimationFrame(()=>t.classList.add("show"));
  clearTimeout(window.__adminToastTimer);
  window.__adminToastTimer=setTimeout(()=>t.classList.remove("show"),2600);
}

let adminSplashOpenedAt=0,adminSplashCloseTimer=null;
function showAdminSplash(message="Procesando..."){
  const splash=$("#adminGlobalSplash"), text=$("#adminGlobalSplashText"), status=$("#adminGlobalSplashStatus");
  if(!splash) return;
  clearTimeout(adminSplashCloseTimer);
  adminSplashOpenedAt=Date.now();
  if(text) text.textContent=message;
  if(status){status.className="admin-global-splash-status";status.innerHTML='<span></span><span></span><span></span>';}
  splash.classList.remove("is-success","is-error","is-closing");
  splash.classList.add("show");
  splash.setAttribute("aria-hidden","false");
  document.body.classList.add("admin-splash-open");
}
function finishAdminSplash(type="success",message="Listo"){
  const splash=$("#adminGlobalSplash"), text=$("#adminGlobalSplashText"), status=$("#adminGlobalSplashStatus");
  if(!splash) return;
  const success=type!=="error";
  splash.classList.toggle("is-success",success);
  splash.classList.toggle("is-error",!success);
  if(text) text.textContent=message;
  if(status) status.innerHTML=`<i class="bi bi-${success?"check-lg":"x-lg"}"></i>`;
  const elapsed=Date.now()-adminSplashOpenedAt;
  const wait=Math.max(160,330-elapsed);
  clearTimeout(adminSplashCloseTimer);
  adminSplashCloseTimer=setTimeout(()=>{
    splash.classList.add("is-closing");
    setTimeout(()=>{
      splash.classList.remove("show","is-success","is-error","is-closing");
      splash.setAttribute("aria-hidden","true");
      document.body.classList.remove("admin-splash-open");
    },140);
  },wait);
}
function setButtonLoading(btn,loading,label="Procesando..."){
  if(!btn) return;
  if(loading){
    if(btn.dataset.loading==="1") return;
    btn.dataset.loading="1";
    btn.dataset.originalHtml=btn.innerHTML;
    btn.disabled=true;
    btn.classList.add("is-loading");
    btn.innerHTML=`<span class="admin-btn-spinner" aria-hidden="true"></span><span>${esc(label)}</span>`;
  }else{
    btn.dataset.loading="0";
    btn.disabled=false;
    btn.classList.remove("is-loading");
    if(btn.dataset.originalHtml!==undefined){btn.innerHTML=btn.dataset.originalHtml;delete btn.dataset.originalHtml;}
  }
}
async function runAdminAction(btn,task,{loading="Procesando...",success="Operación realizada",error="No fue posible completar la operación",successType="success"}={}){
  if(btn?.dataset.loading==="1") return null;
  setButtonLoading(btn,true,loading);
  showAdminSplash(loading);
  try{
    const out=await task();
    const successMessage=success?(typeof success==="function"?success(out):success):"Operación completada";
    if(success) toast(successMessage,successType);
    finishAdminSplash("success",successMessage||"Listo");
    return out;
  }catch(e){
    console.error(e);
    if(isAuthError(e)){finishAdminSplash("error","Sesión expirada");saveSession("");showLogin(authMessageFromError(e));return null;}
    const message=typeof error==="function"?error(e):error;
    toast(message,"error",String(e?.message||e||""));
    finishAdminSplash("error",message||"No fue posible completar la operación");
    return null;
  }finally{setButtonLoading(btn,false)}
}
function applyAdminTheme(theme){
  document.body.classList.toggle("theme-light", theme === "light");
  localStorage.setItem(adminThemeKey, theme);
  $$("[data-admin-theme]").forEach(btn=>btn.classList.toggle("active", btn.dataset.adminTheme === theme));
}
function initAdminTheme(){ applyAdminTheme(localStorage.getItem(adminThemeKey) || "light"); }

function setAdminConnection(state,message){
  const pill=$("#adminConnection"), text=$("#adminConnectionText"), retry=$("#adminRetry");
  if(!pill) return;
  pill.classList.remove("is-online","is-offline","is-loading");
  pill.classList.add(state==="online"?"is-online":state==="offline"?"is-offline":"is-loading");
  if(text) text.textContent=message || (state==="online"?"Conectado":state==="offline"?"Sin conexión":"Conectando...");
  retry?.classList.toggle("hidden", state!=="offline");
}

async function reload(){
  if(!token) throw new Error("SESION_REQUERIDA");
  setAdminConnection("loading","Conectando...");
  const session=await AleAPI.get("adminSession",{__token:token});
  if(!session?.user)throw new Error("SESION_INVALIDA_O_EXPIRADA");
  primeAdminFromUser(session.user);
  await loadAdminModuleQuiet(activeAdminModule(),true);
  setAdminConnection("online","Conectado");
  return data;
}

function renderAll(){
  $("#adminLogo").src=data.config.logo_url||"logo-as-icon.webp";
  $("#kpiProducts").textContent=data.products.length;
  $("#kpiOrders").textContent=data.orders.filter(x=>String(x.estado).toUpperCase()==="PENDIENTE").length;
  $("#kpiRequests").textContent=data.requests.filter(x=>String(x.estado).toUpperCase()==="NUEVA").length;
  $("#kpiStock").textContent=data.products.reduce((s,p)=>s+Number(p.stock||0),0);
  $("#dashboardSummary").innerHTML=`<div class="summary-row"><span>Productos destacados</span><strong>${data.products.filter(p=>String(p.destacado).toUpperCase()==="SI").length}</strong></div><div class="summary-row"><span>Categorías activas</span><strong>${data.categories.length}</strong></div><div class="summary-row"><span>Banners activos</span><strong>${data.banners.length}</strong></div><div class="summary-row"><span>Total pedidos</span><strong>${data.orders.length}</strong></div><div class="summary-row"><span>Mensajes AS Virtual</span><strong>${data.virtualMessages.length}</strong></div><div class="summary-row"><span>Cotizaciones</span><strong>${data.quotes.length}</strong></div>`;
  fillCategorySelects();renderProducts();renderCategories();renderBanners();renderOrders();renderRequests();renderVirtual();renderQuotes();renderWebContent();renderUsers();renderSettings();applyCurrentUser();updateAdminModuleSyncButton();
}

/* R3.10.1 - Actualización inmediata en memoria + reconciliación selectiva */
function refreshLocalDashboardKpis(){
  if($("#kpiProducts")) $("#kpiProducts").textContent=(data.products||[]).length;
  if($("#kpiOrders")) $("#kpiOrders").textContent=(data.orders||[]).filter(x=>String(x.estado).toUpperCase()==="PENDIENTE").length;
  if($("#kpiRequests")) $("#kpiRequests").textContent=(data.requests||[]).filter(x=>String(x.estado).toUpperCase()==="NUEVA").length;
  if($("#kpiStock")) $("#kpiStock").textContent=(data.products||[]).reduce((s,p)=>s+Number(p.stock||0),0);
  if($("#dashboardSummary")) $("#dashboardSummary").innerHTML=`<div class="summary-row"><span>Productos destacados</span><strong>${(data.products||[]).filter(p=>String(p.destacado).toUpperCase()==="SI").length}</strong></div><div class="summary-row"><span>Categorías activas</span><strong>${(data.categories||[]).length}</strong></div><div class="summary-row"><span>Banners activos</span><strong>${(data.banners||[]).length}</strong></div><div class="summary-row"><span>Total pedidos</span><strong>${(data.orders||[]).length}</strong></div><div class="summary-row"><span>Mensajes AS Virtual</span><strong>${(data.virtualMessages||[]).length}</strong></div><div class="summary-row"><span>Cotizaciones</span><strong>${(data.quotes||[]).length}</strong></div>`;
}
function localUpsert(listName,row){
  const list=Array.isArray(data[listName])?data[listName]:[];
  const id=String(row?.id||"");
  const i=list.findIndex(x=>String(x.id||"")===id);
  if(i>=0) list[i]={...list[i],...row}; else list.unshift(row);
  data[listName]=list;
  return row;
}
function localSetStatus(kind,id,status){
  const cfg={order:["orders",renderOrders],request:["requests",renderRequests],virtual:["virtualMessages",renderVirtual],quote:["quotes",renderQuotes]}[String(kind||"").toLowerCase()];
  if(!cfg)return;
  const row=(data[cfg[0]]||[]).find(x=>String(x.id)===String(id));if(row)row.estado=status;
  cfg[1]();refreshLocalDashboardKpis();
  if(kind==="request"||kind==="virtual")renderAdminNotifications();
}
function localDeleteEntity(kind,id){
  const cfg={product:["products",renderProducts],category:["categories",renderCategories],banner:["banners",renderBanners]}[String(kind||"").toLowerCase()];
  if(!cfg)return;
  data[cfg[0]]=(data[cfg[0]]||[]).filter(x=>String(x.id)!==String(id));
  if(kind==="category")fillCategorySelects();
  cfg[1]();refreshLocalDashboardKpis();
}
const adminReconcileTimers={};
function scheduleAdminModuleReconcile(moduleName,delay=900){
  clearTimeout(adminReconcileTimers[moduleName]);
  adminReconcileTimers[moduleName]=setTimeout(async()=>{
    if(!token||!can(moduleName,"read"))return;
    try{
      const r=await AleAPI.get("adminModule",{__token:token,module:moduleName});
      applyAdminModuleSync(moduleName,r||{});
      setAdminConnection("online","Conectado");
    }catch(e){
      console.warn("Reconciliación selectiva",moduleName,e);
      if(isAuthError(e)){saveSession("");showLogin(authMessageFromError(e));}
    }
  },delay);
}

function fillCategorySelects(){
  const categories=(data.categories||[])
    .filter(c=>String(c.activo||"SI").toUpperCase()!=="NO")
    .sort((a,b)=>Number(a.orden||0)-Number(b.orden||0)||String(a.nombre||"").localeCompare(String(b.nombre||"")));
  const opts=categories.map(c=>`<option value="${esc(c.nombre)}">${esc(c.nombre)}</option>`).join("");
  const select=$("#pCategory"), filter=$("#productFilter"), panel=$("#availableCategories");
  if(select){
    select.disabled=!categories.length;
    select.innerHTML=categories.length
      ? '<option value="">Seleccionar categoría</option>'+opts
      : '<option value="">No hay categorías disponibles</option>';
  }
  if(filter) filter.innerHTML='<option value="">Todas las categorías</option>'+opts;
  if(panel){
    panel.innerHTML=categories.length
      ? categories.map(c=>`<button type="button" class="available-category-chip" data-category="${esc(c.nombre)}">${esc(c.nombre)}</button>`).join("")
      : '<div class="categories-empty">No hay categorías creadas. Usa “Administrar categorías” para agregar una.</div>';
    panel.querySelectorAll("[data-category]").forEach(btn=>btn.addEventListener("click",()=>{
      if(select){ select.value=btn.dataset.category; refreshCategoryChipSelection(); }
    }));
  }
  refreshCategoryChipSelection();
}
function refreshCategoryChipSelection(){
  const value=$("#pCategory")?.value||"";
  $$(".available-category-chip").forEach(btn=>btn.classList.toggle("active",btn.dataset.category===value));
}
window.selectProductCategory=name=>{if($("#pCategory")){ $("#pCategory").value=name; refreshCategoryChipSelection(); }};

function table(headers,rows){
  const raw=rows||"";
  const body=raw?raw.replace(/<tr([^>]*)>([\s\S]*?)<\/tr>/g,(full,trAttrs,inner)=>{
    let col=0;
    const cells=inner.replace(/<td([^>]*)>/g,(tag,attrs)=>{
      const label=String(headers[col++]||"").replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
      return `<td${attrs} data-label="${label}">`;
    });
    return `<tr${trAttrs}>${cells}</tr>`;
  }):`<tr class="admin-empty-row"><td colspan="${headers.length}" data-label="">Sin registros</td></tr>`;
  return `<table class="admin-table admin-responsive-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${body}</tbody></table>`;
}
function imgTag(url){return url?`<img class="thumb" src="${esc(url)}" alt="">`:'<div class="thumb"></div>'}
function productImageTag(url,name="Producto"){
  if(!url)return '<div class="thumb"></div>';
  return `<button type="button" class="product-thumb-button" data-product-image="${esc(url)}" data-product-name="${esc(name)}" aria-label="Ampliar imagen de ${esc(name)}"><img class="thumb" src="${esc(url)}" alt="${esc(name)}"><span class="product-thumb-zoom"><i class="bi bi-arrows-fullscreen"></i></span></button>`;
}
window.openProductImageModal=(url,name="Producto")=>{
  const modal=$("#productImageModal"),img=$("#productImageModalImg"),title=$("#productImageModalTitle");
  if(!modal||!img)return;
  img.src=url;img.alt=name||"Producto";if(title)title.textContent=name||"Producto";
  modal.classList.add("show");modal.setAttribute("aria-hidden","false");document.body.classList.add("admin-modal-open");
};
window.closeProductImageModal=()=>{
  const modal=$("#productImageModal"),img=$("#productImageModalImg");
  if(!modal)return;modal.classList.remove("show");modal.setAttribute("aria-hidden","true");if(img)img.removeAttribute("src");document.body.classList.remove("admin-modal-open");
};

function renderProducts(){
  const q=$("#productSearch").value.toLowerCase(), f=$("#productFilter").value;
  const list=data.products.filter(p=>(p.nombre+" "+p.descripcion).toLowerCase().includes(q)&&(!f||p.categoria_nombre===f));
  $("#productsTable").innerHTML=table(["Imagen","Producto","Categoría","Precio","Stock","Destacado","Acciones"],list.map(p=>`<tr><td>${productImageTag(p.image_url,p.nombre)}</td><td><strong>${esc(p.nombre)}</strong><br><small>${esc(p.descripcion||"")}</small></td><td>${esc(p.categoria_nombre||"")}</td><td>${money(p.precio)}</td><td>${Number(p.stock||0)}</td><td>${String(p.destacado).toUpperCase()==="SI"?"Sí":"No"}</td><td><div class="row-actions"><button onclick="editProduct('${p.id}')">Editar</button><button class="danger" onclick="removeEntity('product','${p.id}',this)">Eliminar</button></div></td></tr>`).join(""));
}
$("#productSearch").addEventListener("input",renderProducts);$("#productFilter").addEventListener("change",renderProducts);$("#pCategory")?.addEventListener("change",refreshCategoryChipSelection);
$("#newProduct").addEventListener("click",()=>{clearProduct();$("#productEditor").classList.remove("hidden")});
function clearProduct(){["pId","pImageId","pImageUrl","pName","pPrice","pStock","pOccasion","pDescription"].forEach(id=>$("#"+id).value="");if($("#pCategory"))$("#pCategory").value="";$("#pFeatured").checked=false;$("#pImage").value="";refreshCategoryChipSelection()}
window.editProduct=id=>{const p=data.products.find(x=>x.id===id);if(!p)return;$("#pId").value=p.id;$("#pImageId").value=p.drive_file_id||"";$("#pImageUrl").value=p.image_url||"";$("#pName").value=p.nombre||"";$("#pPrice").value=p.precio||"";$("#pCategory").value=p.categoria_nombre||"";$("#pStock").value=p.stock||0;$("#pOccasion").value=p.ocasion||"";$("#pDescription").value=p.descripcion||"";$("#pFeatured").checked=String(p.destacado).toUpperCase()==="SI";refreshCategoryChipSelection();$("#productEditor").classList.remove("hidden")}
$("#saveProduct").addEventListener("click",async e=>{const btn=e.currentTarget;await runAdminAction(btn,async()=>{let imageId=$("#pImageId").value;let imageUrl=$("#pImageUrl").value;const file=$("#pImage").files[0];if(file){const uploaded=await upload(file,"PRODUCTOS");imageId=uploaded.fileId;imageUrl=uploaded.imageUrl||imageUrl;}const payload={id:$("#pId").value,nombre:$("#pName").value.trim(),descripcion:$("#pDescription").value.trim(),precio:Number($("#pPrice").value||0),categoria_nombre:$("#pCategory").value,stock:Number($("#pStock").value||0),drive_file_id:imageId,image_url:imageUrl,destacado:$("#pFeatured").checked?"SI":"NO",activo:"SI",ocasion:$("#pOccasion").value.trim()};const out=await AleAPI.post("saveProduct",payload,token);payload.id=out.id||payload.id;localUpsert("products",payload);$("#productEditor").classList.add("hidden");renderProducts();refreshLocalDashboardKpis();scheduleAdminModuleReconcile("products");return payload},{loading:"Guardando...",success:"Producto guardado correctamente",error:"No fue posible guardar el producto"})});

function renderCategories(){
  $("#categoriesTable").innerHTML=table(["Imagen","Categoría","Descripción","Orden","Acciones"],data.categories.map(c=>`<tr><td>${imgTag(c.image_url)}</td><td><strong>${esc(c.nombre)}</strong></td><td>${esc(c.descripcion||"")}</td><td>${Number(c.orden||0)}</td><td><div class="row-actions"><button onclick="editCategory('${c.id}')">Editar</button><button class="danger" onclick="removeEntity('category','${c.id}',this)">Eliminar</button></div></td></tr>`).join(""));
}
