/* R3.9.0 - Contenido Web administrable */
const webContentDefaults=Array.isArray(window.ASCMS_DEFAULTS)?window.ASCMS_DEFAULTS:[];
let webContentDirty=new Set();
let webContentDraft=new Map();
function webContentServerMap(){return new Map((data.contentRows||[]).map(r=>[String(r.clave||r.key||''),r]))}
function webContentRowsMerged(){
  const server=webContentServerMap();
  return webContentDefaults.map((d,i)=>{const key=String(d.key),hasServer=server.has(key),r=server.get(key)||{},saved=hasServer?String(r.valor??''):String(d.value??''),value=webContentDraft.has(key)?webContentDraft.get(key):saved;return {clave:key,grupo:String(d.group||r.grupo||'General'),etiqueta:String(d.label||r.etiqueta||d.value||d.key),valor:String(value??''),tipo:String(d.type||r.tipo||'text'),orden:Number(r.orden||i+1),activo:String(r.activo||'SI'),defaultValue:String(d.value??'')}});
}
function webContentGroups(){return [...new Set(webContentRowsMerged().map(r=>r.grupo))].sort((a,b)=>a.localeCompare(b,'es'))}
function updateWebContentDirtyLabel(){const el=$('#webContentDirtyText');if(el)el.textContent=webContentDirty.size?`${webContentDirty.size} cambio${webContentDirty.size===1?'':'s'} pendiente${webContentDirty.size===1?'':'s'} de publicar`:'Sin cambios pendientes'}
function renderWebContent(){
  const editor=$('#webContentEditor'),groupSel=$('#webContentGroup');if(!editor||!groupSel)return;
  const currentGroup=groupSel.value;
  groupSel.innerHTML='<option value="">Todos los módulos</option>'+webContentGroups().map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('');
  if([...groupSel.options].some(o=>o.value===currentGroup))groupSel.value=currentGroup;
  const q=String($('#webContentSearch')?.value||'').trim().toLowerCase(),g=groupSel.value;
  const rows=webContentRowsMerged().filter(r=>(!g||r.grupo===g)&&(!q||`${r.etiqueta} ${r.valor} ${r.clave} ${r.grupo}`.toLowerCase().includes(q)));
  if(!rows.length){editor.innerHTML='<div class="cms-empty"><i class="bi bi-search"></i><strong>Sin resultados</strong><span>Cambia el filtro o la búsqueda.</span></div>';updateWebContentDirtyLabel();return;}
  const grouped=new Map();rows.forEach(r=>{if(!grouped.has(r.grupo))grouped.set(r.grupo,[]);grouped.get(r.grupo).push(r)});
  editor.innerHTML=[...grouped.entries()].map(([group,items])=>`<section class="cms-group"><div class="cms-group-head"><span>${esc(group)}</span><small>${items.length} texto${items.length===1?'':'s'}</small></div><div class="cms-fields">${items.map(r=>{const control=r.tipo==='textarea'||r.valor.length>90?`<textarea class="cms-editor-input" data-cms-key="${esc(r.clave)}" rows="3">${esc(r.valor)}</textarea>`:`<input class="cms-editor-input" data-cms-key="${esc(r.clave)}" value="${esc(r.valor)}">`;return `<label class="cms-field ${webContentDirty.has(r.clave)?'is-dirty':''}"><span class="cms-field-title"><strong>${esc(r.etiqueta)}</strong><small>${esc(r.clave)}</small></span>${control}<span class="cms-field-actions"><button type="button" class="cms-reset-btn" data-cms-reset="${esc(r.clave)}"><i class="bi bi-arrow-counterclockwise"></i> Restaurar original</button></span></label>`}).join('')}</div></section>`).join('');
  $$('.cms-editor-input').forEach(el=>el.addEventListener('input',()=>{webContentDraft.set(el.dataset.cmsKey,el.value);webContentDirty.add(el.dataset.cmsKey);el.closest('.cms-field')?.classList.add('is-dirty');updateWebContentDirtyLabel()}));
  $$('[data-cms-reset]').forEach(btn=>btn.addEventListener('click',()=>{const key=btn.dataset.cmsReset,def=webContentDefaults.find(x=>String(x.key)===key);if(!def)return;const input=$(`.cms-editor-input[data-cms-key="${CSS.escape(key)}"]`);if(input){input.value=String(def.value??'');input.dispatchEvent(new Event('input',{bubbles:true}))}}));
  updateWebContentDirtyLabel();
}
function collectWebContentPayload(){
  const merged=new Map(webContentRowsMerged().map(r=>[r.clave,r]));
  $$('.cms-editor-input').forEach(el=>{const r=merged.get(el.dataset.cmsKey);if(r)r.valor=el.value});
  return [...merged.values()].filter(r=>webContentDirty.has(r.clave)).map((r,i)=>({clave:r.clave,grupo:r.grupo,etiqueta:r.etiqueta,valor:r.valor,tipo:r.tipo,orden:r.orden||i+1,activo:'SI'}));
}
async function saveWebContent(btn){
  if(!webContentDirty.size){toast('No hay cambios pendientes','info');return;}
  await runAdminAction(btn,async()=>{const rows=collectWebContentPayload();const out=await AleAPI.post('saveWebContent',{rows},token);const map=new Map((data.contentRows||[]).map(r=>[String(r.clave||''),r]));rows.forEach(r=>map.set(r.clave,r));data.contentRows=[...map.values()];data.publicVersion=out.version||data.publicVersion;webContentDirty.clear();webContentDraft.clear();renderWebContent();return out},{loading:'Publicando...',success:'Contenido publicado. La web lo tomará al recargar o navegar.',error:'No fue posible publicar el contenido'});
}
