$("#clearWhatsAppToken")?.addEventListener("click",async e=>{if(!confirm("¿Quitar el token de WhatsApp Business?"))return;const btn=e.currentTarget;await runAdminAction(btn,async()=>{const out=await AleAPI.post("saveWhatsAppCloudConfig",{clear_token:true},token);data.whatsappCloud=out.status||{configured:false};renderSettings();return out},{loading:"Quitando...",success:"Token de WhatsApp eliminado",error:"No fue posible quitar el token"})});


/* R3.10.0 - Sincronización selectiva del módulo abierto */
function activeAdminModule(){
  return $(".admin-nav button.active")?.dataset.module || "dashboard";
}
function adminModuleLabel(moduleName){
  return permissionModules.find(x=>x[0]===moduleName)?.[1] || "Módulo";
}
function updateAdminModuleSyncButton(){
  const btn=$("#adminModuleSync"); if(!btn) return;
  const moduleName=activeAdminModule(),label=adminModuleLabel(moduleName);
  btn.dataset.module=moduleName;
  btn.title=`Sincronizar ${label}`;
  btn.setAttribute("aria-label",`Sincronizar ${label}`);
  btn.classList.toggle("hidden",!can(moduleName,"read"));
}
function renderDashboardFromSync(s={}){
  if($("#kpiProducts")) $("#kpiProducts").textContent=Number(s.products||0);
  if($("#kpiOrders")) $("#kpiOrders").textContent=Number(s.ordersPending||0);
  if($("#kpiRequests")) $("#kpiRequests").textContent=Number(s.requestsNew||0);
  if($("#kpiStock")) $("#kpiStock").textContent=Number(s.stock||0);
  if($("#dashboardSummary")) $("#dashboardSummary").innerHTML=`<div class="summary-row"><span>Productos destacados</span><strong>${Number(s.featured||0)}</strong></div><div class="summary-row"><span>Categorías activas</span><strong>${Number(s.categories||0)}</strong></div><div class="summary-row"><span>Banners activos</span><strong>${Number(s.banners||0)}</strong></div><div class="summary-row"><span>Total pedidos</span><strong>${Number(s.totalOrders||0)}</strong></div><div class="summary-row"><span>Mensajes AS Virtual</span><strong>${Number(s.virtualMessages||0)}</strong></div><div class="summary-row"><span>Cotizaciones</span><strong>${Number(s.quotes||0)}</strong></div>`;
}
function applyAdminModuleSync(moduleName,r={},fromCache=false){
  if(!fromCache)saveAdminModuleCache(moduleName,r);
  if(moduleName==="dashboard"){renderDashboardFromSync(r.dashboard||{});return;}
  if(moduleName==="products"){
    data.products=Array.isArray(r.products)?r.products:data.products;
    data.categories=Array.isArray(r.categories)?r.categories:data.categories;
    fillCategorySelects();renderProducts();return;
  }
  if(moduleName==="categories"){
    data.categories=Array.isArray(r.categories)?r.categories:data.categories;
    fillCategorySelects();renderCategories();return;
  }
  if(moduleName==="banners"){
    data.banners=Array.isArray(r.banners)?r.banners:data.banners;renderBanners();return;
  }
  if(moduleName==="orders"){
    data.orders=Array.isArray(r.orders)?r.orders:data.orders;renderOrders();return;
  }
  if(moduleName==="requests"){
    data.requests=Array.isArray(r.requests)?r.requests:data.requests;renderRequests();renderAdminNotifications();return;
  }
  if(moduleName==="virtual"){
    data.virtualMessages=Array.isArray(r.virtualMessages)?r.virtualMessages:data.virtualMessages;renderVirtual();renderAdminNotifications();return;
  }
  if(moduleName==="office"){
    data.quotes=Array.isArray(r.quotes)?r.quotes:data.quotes;renderQuotes();return;
  }
  if(moduleName==="content"){
    data.contentRows=Array.isArray(r.contentRows)?r.contentRows:data.contentRows;
    if(r.publicVersion!==undefined)data.publicVersion=r.publicVersion;
    renderWebContent();return;
  }
  if(moduleName==="users"){
    data.users=Array.isArray(r.users)?r.users:data.users;renderUsers();return;
  }
  if(moduleName==="settings"){
    data.config=r.config||data.config;
    data.whatsappCloud=r.whatsappCloud||data.whatsappCloud;
    if($("#adminLogo")) $("#adminLogo").src=data.config.logo_url||"logo-as-icon.webp";
    renderSettings();return;
  }
}
const adminModuleLoadedAt={};
const adminModuleLoading={};
const adminModuleCachePrefix="asServiciosAdminModuleCacheV3";
const adminModuleFreshMs=120000;
function adminCacheUserId(){const u=data.currentUser||{};return String(u.id||u.usuario||u.email||"anon").replace(/[^a-zA-Z0-9_.-]/g,"_")}
function adminModuleCacheKey(moduleName){return `${adminModuleCachePrefix}:${adminCacheUserId()}:${moduleName}`}
function saveAdminModuleCache(moduleName,payload){try{localStorage.setItem(adminModuleCacheKey(moduleName),JSON.stringify({ts:Date.now(),payload}))}catch(_){}}
function readAdminModuleCache(moduleName){try{const raw=localStorage.getItem(adminModuleCacheKey(moduleName));if(!raw)return null;const parsed=JSON.parse(raw);return parsed&&parsed.payload?parsed:null}catch(_){return null}}
function hydrateAdminModuleCache(){
  const loaded={};
  ["dashboard","products","categories","banners","orders","requests","virtual","office","content","users","settings"].forEach(moduleName=>{
    if(!can(moduleName,"read"))return;
    const c=readAdminModuleCache(moduleName);if(!c)return;
    applyAdminModuleSync(moduleName,c.payload,true);
    adminModuleLoadedAt[moduleName]=Number(c.ts||0);
    loaded[moduleName]=true;
  });
  return loaded;
}

function primeAdminFromUser(user){
  data.currentUser=user||null;
  data.permissions=(user&&user.permisos)||{};
  const cached=hydrateAdminModuleCache();
  applyCurrentUser();
  if(!cached.dashboard)renderDashboardFromSync({});
  renderAdminNotifications?.();
  updateAdminModuleSyncButton();
}

async function loadAdminModuleQuiet(moduleName,force=false){
  moduleName=String(moduleName||"dashboard").toLowerCase();
  if(!token||!data.currentUser||!can(moduleName,"read"))return null;
  const last=Number(adminModuleLoadedAt[moduleName]||0);
  if(!force&&Date.now()-last<adminModuleFreshMs)return null;
  if(adminModuleLoading[moduleName])return adminModuleLoading[moduleName];

  const label=adminModuleLabel(moduleName);
  setAdminConnection("loading",`Cargando ${label}...`);
  const task=(async()=>{
    try{
      const r=await AleAPI.get("adminModule",{__token:token,module:moduleName});
      applyAdminModuleSync(moduleName,r||{});
      adminModuleLoadedAt[moduleName]=Date.now();
      setAdminConnection("online","Conectado");
      return r;
    }catch(e){
      console.warn("Carga selectiva",moduleName,e);
      if(isAuthError(e)){saveSession("");showLogin(authMessageFromError(e));}
      else setAdminConnection("offline","Conexión lenta");
      return null;
    }finally{
      delete adminModuleLoading[moduleName];
    }
  })();
  adminModuleLoading[moduleName]=task;
  return task;
}

async function syncOpenAdminModule(btn=$("#adminModuleSync")){
  const moduleName=activeAdminModule(),label=adminModuleLabel(moduleName);
  if(!can(moduleName,"read")){toast("No tienes permiso para sincronizar este módulo","error");return null;}
  return runAdminAction(btn,async()=>{
    setAdminConnection("loading","Sincronizando...");
    try{
      const r=await AleAPI.get("adminModule",{__token:token,module:moduleName});
      applyAdminModuleSync(moduleName,r||{});
      setAdminConnection("online","Conectado");
      return r;
    }catch(e){setAdminConnection("offline","Sin conexión");throw e;}
  },{
    loading:`Sincronizando ${label}...`,
    success:`Sincronización completada: ${label}`,
    error:`No fue posible sincronizar ${label}`
  });
}

async function upload(file,kind){if(file.size>6*1024*1024)throw new Error("IMAGEN_MUY_GRANDE");const dataUrl=await AleAPI.fileToDataUrl(file);return AleAPI.post("uploadImage",{kind,fileName:file.name,dataUrl},token)}

